-- Publish the reviewed official 2026 TCG Masters qualified-competitor pool and open Pick 10.
-- The source records earned invitations, not confirmed registration or attendance.

begin;

lock table public.worlds_pick_events in row exclusive mode;
lock table public.worlds_pick_competitors in row exclusive mode;

do $preflight$
begin
  if (select count(*) from public.worlds_pick_events where id = '2026-tcg-masters') <> 1 then
    raise exception 'Expected exactly one staged 2026 TCG Masters event.';
  end if;

  if exists (
    select 1 from public.worlds_pick_events
    where id = '2026-tcg-masters'
      and (status <> 'draft' or discipline <> 'tcg' or entry_unit <> 'individual'
        or division <> 'Masters' or picks_required <> 10
        or locks_at <> '2026-08-28T07:00:00Z'::timestamptz)
  ) then
    raise exception 'The staged 2026 TCG Masters contract changed; review it before opening entries.';
  end if;

  if exists (select 1 from public.worlds_pick_competitors where event_id = '2026-tcg-masters') then
    raise exception 'TCG competitors already exist; reconcile them before applying migration 376.';
  end if;

  if exists (select 1 from public.worlds_pick_entries where event_id = '2026-tcg-masters') then
    raise exception 'TCG entries already exist; migration 376 only opens a zero-entry event.';
  end if;

  if (select count(*) from public.worlds_result_sources where event_id = '2026-tcg-masters') <> 1
     or exists (
       select 1 from public.worlds_result_sources
       where event_id = '2026-tcg-masters'
         and (enabled or state <> 'disabled' or feed_url is not null or external_event_id is not null)
     ) then
    raise exception 'The TCG result source must remain disabled and unconfigured.';
  end if;

  if has_table_privilege('anon', 'public.worlds_pick_competitors', 'select')
     or has_table_privilege('authenticated', 'public.worlds_pick_entries', 'select') then
    raise exception 'Direct Worlds table reads must remain revoked.';
  end if;

  if not has_function_privilege('anon', 'public.get_worlds_pick_hub(text)', 'execute')
     or not has_function_privilege('authenticated', 'public.get_worlds_pick_hub(text)', 'execute')
     or not has_function_privilege('authenticated', 'public.save_worlds_pick_entry(text,text[],text)', 'execute') then
    raise exception 'The Worlds Pick 10 RPC grants are incomplete.';
  end if;
end;
$preflight$;

