update public.worlds_pick_events
set display_name = '2026 TCG Worlds Pick 10',
    status = 'open',
    roster_source_url = 'https://worlds.pokemon.com/en-us/about/qualified/',
    roster_checked_at = '2026-08-11',
    updated_at = now()
where id = '2026-tcg-masters';

do $postflight$
begin
  if (select count(*) from public.worlds_pick_competitors where event_id = '2026-tcg-masters') <> 880
     or (select count(distinct slug) from public.worlds_pick_competitors where event_id = '2026-tcg-masters') <> 880
     or (select count(distinct source_order) from public.worlds_pick_competitors where event_id = '2026-tcg-masters') <> 880 then
    raise exception 'The reviewed TCG pool must contain 880 unique competitors and source orders.';
  end if;

  if exists (
    select 1 from public.worlds_pick_competitors
    where event_id = '2026-tcg-masters'
      and (attendance_status <> 'invite_earned' or not is_selectable or score_points <> 0
        or source_url <> 'https://worlds.pokemon.com/en-us/about/qualified/'
        or source_checked_at <> '2026-08-11')
  ) then
    raise exception 'The TCG pool contains an unexpected status, score, or source.';
  end if;

  if not exists (
    select 1 from public.worlds_pick_events
    where id = '2026-tcg-masters'
      and status = 'open'
      and roster_source_url = 'https://worlds.pokemon.com/en-us/about/qualified/'
      and roster_checked_at = '2026-08-11'
  ) then
    raise exception 'The 2026 TCG Masters event did not open on the reviewed roster.';
  end if;

  if exists (select 1 from public.worlds_pick_entries where event_id = '2026-tcg-masters') then
    raise exception 'Opening the TCG pool must not create prediction entries.';
  end if;

  if exists (
    select 1 from public.worlds_result_sources
    where event_id = '2026-tcg-masters'
      and (enabled or state <> 'disabled' or feed_url is not null or external_event_id is not null)
  ) then
    raise exception 'Opening TCG Pick 10 must not enable results polling.';
  end if;
end;
$postflight$;

commit;
